<script setup>
import{computed,nextTick,onBeforeUnmount,onMounted,ref,shallowRef}from'vue';
import{createStore,eventDraft,eventFromDraft,ordered,reorder,validateDocument,validateSettings}from'./countdown-model.js';
import{a as LunarYear}from'./original/index-foMHgrIw.js';
const props=defineProps({host:Object,initialSettings:Object,initialDocument:Object,variant:{type:String,default:'countdown'}});
const settings=ref(validateSettings(props.initialSettings)),document=shallowRef(validateDocument(props.initialDocument)),now=ref(Date.now()),draft=ref({}),themeDraft=ref({}),editor=ref(),confirm=ref(),selector=ref(),themeDialog=ref(),editError=ref(''),themeError=ref(''),operationError=ref(''),saving=ref(false),themeSaving=ref(false),pendingDelete=ref(''),dragged=ref('');
let alive=true,timer;
const store=createStore(document.value,value=>props.host.request('storage.set',value),{preview:props.host.preview,changed:value=>{document.value=value;}});
props.host.beforeLibrarySwitch=async()=>{if(saving.value||themeSaving.value||[editor,confirm,selector,themeDialog].some(dialog=>dialog.value?.open))throw Error('请先保存或关闭倒计时编辑窗口');await store.flush();};
const events=computed(()=>ordered(document.value,now.value)),selected=computed(()=>events.value.find(item=>item.id===document.value.selectedId)||null),isList=computed(()=>props.variant==='countdown-list');
const theme=computed(()=>({'--widget-background-color':settings.value.background,'--widget-color':settings.value.foreground,'--widget-primary-color':settings.value.primaryColor,'--widget-border-radius':settings.value.radius+'px'}));
const titleStyle=computed(()=>({background:`linear-gradient(180deg, ${settings.value.primaryColor} 0%, color-mix(in srgb, ${settings.value.primaryColor} 100%, #000 20%) 100%)`}));
const lunarMonths=computed(()=>{const year=Number(draft.value.year);if(!Number.isInteger(year)||year<1949||year>2099)return[];return LunarYear.fromYear(year).getMonthsInYear().map(month=>({value:month.getMonth(),label:(month.getMonth()<0?'闰':'')+Math.abs(month.getMonth())+'月'}));});
function openSelector(){selector.value.showModal();}
function openNew(){const seed={id:'draft',name:'',note:'',dateType:0,recurrence:'',sourceDateTime:new Date(now.value).toISOString()};draft.value=eventDraft(seed);delete draft.value.id;editError.value='';editor.value.showModal();}
function openEdit(id){const value=document.value.events.find(item=>item.id===id);if(!value)return;draft.value=eventDraft(value);editError.value='';editor.value.showModal();}
function switchDateType(type){try{const current=eventFromDraft({...draft.value,name:draft.value.name||'日期转换'},null,now.value,()=> 'draft');const converted=eventDraft(current);draft.value={...draft.value,...converted,id:draft.value.id,name:draft.value.name,dateType:type,recurrence:type===1?'':draft.value.recurrence};}catch(error){editError.value=String(error?.message||error);}}
async function saveEvent(){
  if(props.host.preview||saving.value)return;saving.value=true;editError.value='';
  try{const previous=document.value.events.find(item=>item.id===draft.value.id),value=eventFromDraft(draft.value,previous,Date.now());await store.update(next=>{const index=next.events.findIndex(item=>item.id===value.id);if(index<0)next.events.push(value);else next.events[index]=value;if(!next.selectedId)next.selectedId=value.id;});if(alive)editor.value.close();}
  catch(error){if(alive)editError.value='倒计时未保存：'+String(error?.message||error);}finally{saving.value=false;}
}
async function run(action){operationError.value='';try{await action();}catch(error){if(alive)operationError.value='操作未保存：'+String(error?.message||error);}}
async function selectEvent(id){await run(()=>store.update(next=>{if(!next.events.some(item=>item.id===id))throw Error('所选倒计时不存在');next.selectedId=id;}));}
async function toggleSort(){await run(()=>store.update(next=>{next.sort=next.sort==='asc'?'desc':'asc';}));}
async function dropBefore(from,to){if(!from||from===to)return;await run(()=>store.update(next=>{const byId=new Map(next.events.map(item=>[item.id,item]));const sorted=ordered(next,now.value).map(item=>byId.get(item.id));if(to===''){next.events=sorted.filter(item=>item.id!==from);const moved=byId.get(from);if(!moved)throw Error('拖动项目不存在');next.events.push(moved);next.events.forEach((item,index)=>{item.sortOrder=index;});}else Object.assign(next,reorder({...next,events:sorted},from,to));}));dragged.value='';}
function dragStart(event,id){if(event.button!==0||props.host.preview)return;dragged.value=id;event.currentTarget.setPointerCapture(event.pointerId);}
function dragEnd(event){const from=dragged.value;if(!from)return;const target=window.document.elementFromPoint(event.clientX,event.clientY)?.closest('[data-event-id]');dragged.value='';if(!target||target.dataset.eventId===from)return;const bounds=target.getBoundingClientRect(),index=events.value.findIndex(item=>item.id===target.dataset.eventId),before=event.clientY<bounds.top+bounds.height/2?target.dataset.eventId:events.value[index+1]?.id||'';void dropBefore(from,before);}
function askDelete(id){pendingDelete.value=id;confirm.value.showModal();}
async function remove(){if(props.host.preview||saving.value)return;saving.value=true;operationError.value='';try{await store.update(next=>{next.events=next.events.filter(item=>item.id!==pendingDelete.value);if(next.selectedId===pendingDelete.value)next.selectedId=next.events[0]?.id||'';});if(alive){confirm.value.close();editor.value?.close();}}catch(error){if(alive)operationError.value='删除未保存：'+String(error?.message||error);}finally{saving.value=false;}}
function openTheme(){themeDraft.value={...settings.value};themeError.value='';themeDialog.value.showModal();}
async function saveTheme(){if(props.host.preview||themeSaving.value)return;themeSaving.value=true;themeError.value='';try{const next=validateSettings({...themeDraft.value,radius:Number(themeDraft.value.radius)});for(const key of['background','foreground','primaryColor'])if(!CSS.supports('color',next[key]))throw Error('颜色格式无效');const saved=validateSettings(await props.host.request('settings.update',next));if(alive){settings.value=saved;themeDialog.value.close();}}catch(error){if(alive)themeError.value='主题未保存：'+String(error?.message||error);}finally{themeSaving.value=false;}}
function dispose(){alive=false;clearInterval(timer);store.dispose();}
onBeforeUnmount(dispose);onMounted(async()=>{await props.host.ready();if(!alive)return;timer=setInterval(()=>{now.value=Date.now();},1000);if(!props.host.preview&&new URLSearchParams(location.search).get('verify')==='widgetjs')await verifySession();});
async function verifySession(){
  const prior=document.value.verification,label='期限'+props.host.instanceId.slice(0,8);let invalidSaveRejected=prior?.invalidSaveRejected===true;
  if(!prior?.uiVerified){
    openNew();await nextTick();Object.assign(draft.value,{name:'',date:'2027-01-01',dateType:0,recurrence:'RRULE:FREQ=MONTHLY'});const before=JSON.stringify((await props.host.request('storage.get')).events);await saveEvent();invalidSaveRejected=JSON.stringify((await props.host.request('storage.get')).events)===before&&editError.value.includes('未保存');draft.value.name=label;draft.value.note='独立保存验证';await nextTick();window.document.getElementById('countdown-event-form').requestSubmit();for(let n=0;n<100&&saving.value;n++)await new Promise(resolve=>setTimeout(resolve,50));if(saving.value||editor.value.open)throw Error('倒计时表单保存未完成：'+editError.value);const created=document.value.events.find(item=>item.name===label);if(!created)throw Error('倒计时未写入');await selectEvent(created.id);await toggleSort();
    openTheme();themeDraft.value.radius=12;themeDraft.value.background='#'+props.host.instanceId.replaceAll('-','').slice(0,6);await saveTheme();
  }
  await nextTick();const saved=await props.host.request('settings.get'),stored=await props.host.request('storage.get'),chosen=stored.events.find(item=>item.id===stored.selectedId),configurationSaved=chosen?.name===label&&saved.radius===12&&stored.sort==='desc';
  const stylesLoaded=getComputedStyle(window.document.querySelector('.widget')).borderRadius==='12px'&&(isList.value?getComputedStyle(window.document.querySelector('.scroll-wrapper')).overflowY==='auto':getComputedStyle(window.document.querySelector('.days')).fontSize==='72px'),imagesLoaded=isList.value?window.document.querySelectorAll('.event').length===stored.events.length:window.document.querySelectorAll('.stack .card').length===2;
  await store.update(next=>{next.verification={uiVerified:configurationSaved&&invalidSaveRejected&&stylesLoaded&&imagesLoaded,configurationSaved,invalidSaveRejected,stylesLoaded,imagesLoaded,savedLabel:label,runtimeLoads:(prior?.runtimeLoads??0)+1,renderedText:window.document.querySelector(isList.value?'.event-list-wrapper':'.countdown-widget').textContent.slice(0,500),localOnly:true,origin:location.origin};});
}
</script>
<template><main class="widget" :class="{list:isList}" :style="theme"><section v-if="isList" class="root"><header class="title"><span>倒计时列表</span><div class="actions"><button type="button" aria-label="添加倒计时" title="添加倒计时" @click="openNew">＋</button><button type="button" aria-label="切换日期排序" :title="document.sort==='asc'?'日期升序':'日期降序'" @click="toggleSort">⇅</button></div></header><div class="scroll-wrapper"><div class="event-list-wrapper"><div v-for="item in events" :key="item.id" class="draggable" :data-event-id="item.id"><button type="button" class="drag-handle" aria-label="拖动排序" :disabled="host.preview" @pointerdown="dragStart($event,item.id)" @pointerup="dragEnd" @pointercancel="dragged=''">⠿</button><button type="button" class="event" :class="{today:item.today,past:item.past}" :aria-label="'编辑倒计时 '+item.name" @click="openEdit(item.id)"><div class="info"><div class="event-name">{{item.name}}</div><div class="date">{{item.dateText}}</div><div class="note">{{item.note}}</div></div><div class="countdown"><div class="days">{{Math.abs(item.days)}}</div><div class="unit">天</div></div></button></div><button v-if="!events.length" class="empty" type="button" @click="openNew">添加倒计时</button></div></div></section><section v-else-if="selected" class="countdown-widget"><header class="title" :style="titleStyle"><button type="button" @click="openSelector">{{selected.name}}{{selected.cardDays<0?'已经':'还有'}}</button></header><div class="stack"><div class="card"/><div class="card"/><div class="info"><button type="button" class="days" @click="openSelector">{{Math.abs(selected.cardDays)}}</button><span class="date">{{selected.cardDateText}}</span></div></div></section><div v-else class="empty"><button type="button" @click="openSelector">设置倒计时</button></div><button class="configure" type="button" aria-label="倒计时主题设置" title="倒计时主题设置" @click="openTheme">⚙</button><output class="status" role="status">{{host.preview?'预览 · 不保存':operationError}}</output>
<dialog ref="selector"><h2>选择倒计时</h2><div class="selection"><div v-for="item in events" :key="item.id" class="selection-row"><label><input type="radio" name="countdown-selected" :checked="document.selectedId===item.id" :disabled="host.preview" @change="selectEvent(item.id)"><span>{{item.name}}<small>{{item.dateText}}</small></span></label><button type="button" @click="openEdit(item.id)">编辑</button><button type="button" @click="askDelete(item.id)">删除</button></div></div><footer><button type="button" @click="openNew">添加倒计时</button><button type="button" @click="selector.close()">关闭</button></footer></dialog>
<dialog ref="editor" @cancel="saving&&$event.preventDefault()"><form id="countdown-event-form" @submit.prevent="saveEvent"><h2>{{draft.id?'编辑':'添加'}}倒计时</h2><label>名称<input v-model="draft.name" required maxlength="15" placeholder="倒计时名称"></label><label>备注<input v-model="draft.note" maxlength="4096" placeholder="添加备注"></label><label>日期类型<select :value="draft.dateType" @change="switchDateType(Number($event.target.value))"><option :value="0">公历</option><option :value="1">农历</option></select></label><label v-if="draft.dateType===0">目标日期<input v-model="draft.date" type="date" required></label><fieldset v-else><legend>农历日期</legend><label>年份<input v-model="draft.year" type="number" min="1949" max="2099" required></label><label>月份<select v-model="draft.month"><option v-for="month in lunarMonths" :key="month.value" :value="month.value">{{month.label}}</option></select></label><label>日<input v-model="draft.dayOfMonth" type="number" min="1" max="30" required></label></fieldset><label v-if="draft.dateType===0">重复<select v-model="draft.recurrence"><option value="">不重复</option><option value="RRULE:FREQ=DAILY">每天</option><option value="RRULE:FREQ=WEEKLY">每周</option><option value="RRULE:FREQ=MONTHLY">每月</option></select></label><p class="error" role="status">{{editError}}</p><footer><button v-if="draft.id" type="button" :disabled="saving||host.preview" @click="askDelete(draft.id)">删除</button><button type="button" :disabled="saving" @click="editor.close()">取消</button><button type="submit" :disabled="saving||host.preview">{{saving?'保存中':'保存'}}</button></footer></form></dialog>
<dialog ref="confirm" @cancel="saving&&$event.preventDefault()"><h2>删除倒计时？</h2><p>此操作删除当前数据源的倒计时；使用共享库时会影响连接它的实例。</p><p class="error">{{operationError}}</p><footer><button type="button" :disabled="saving" @click="confirm.close()">取消</button><button type="button" :disabled="saving||host.preview" @click="remove">确认删除</button></footer></dialog>
<dialog ref="themeDialog" @cancel="themeSaving&&$event.preventDefault()"><form @submit.prevent="saveTheme"><h2>倒计时外观</h2><label>背景颜色<input v-model="themeDraft.background" maxlength="80" required></label><label v-if="isList">文字颜色<input v-model="themeDraft.foreground" maxlength="80" required></label><label>主题颜色<input v-model="themeDraft.primaryColor" maxlength="80" required></label><label>圆角<input v-model="themeDraft.radius" type="number" min="0" max="50" required></label><p class="error" role="status">{{themeError}}</p><footer><button type="button" :disabled="themeSaving" @click="themeDialog.close()">取消</button><button type="submit" :disabled="themeSaving||host.preview">{{themeSaving?'保存中':'保存'}}</button></footer></form></dialog></main></template>
